--- the commentstring for the current line (from its first non-blank)
---@return string
function _MODULE.get()
  local row = vim.api.nvim_win_get_cursor(0)[1] - 1
  local line = vim.api.nvim_buf_get_lines(0, row, row + 1, false)[1] or ""
  local col = (line:match("^%s*()") or 1) - 1
  local __MIDNIGHT_TMP_3__ do local __MIDNIGHT_TMP_4__, __MIDNIGHT_TMP_5__ = pcall(function() return vim.treesitter.get_node({pos = {row, col}, ignore_injections = false}) end) if __MIDNIGHT_TMP_4__ then __MIDNIGHT_TMP_3__ = __MIDNIGHT_TMP_5__ else
      return _MODULE.code
    end end local node = __MIDNIGHT_TMP_3__
  while node and parts[node:type()] do
    node = node:parent()
  end
  if node and children[node:type()] then
    local parent = node:parent()
    if parent and parent:type() == "markup_element" then return _MODULE.markup end
  end
  return _MODULE.code
end

